// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(address caller, uint256 val) public {
        if (caller == address(0)) caller = address(1);

        bool ok;
        vm.prank(caller);
        try c.SetMinSum(val) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.MinSum() == val);
    }
}
